#!/usr/bin/env bash
# src/agentic/k8s/kube.sh
# Reach a project's Kubernetes clusters through the kubeconfig `devbot init`
# generated for it. The generated file is named "<project>-<hash>.yaml" and its
# contexts come from the global `kubectl` catalogue, so neither is something a
# caller should have to reconstruct — that is what this command is for.
#
# Never use the plain ~/.kube/config for these clusters: its contexts are SSO
# exec contexts that expire, while the generated ones use the devbot profile.
set -euo pipefail

MODULE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=./functions.sh
source "${MODULE_DIR}/functions.sh"

_usage() {
  cat <<'EOF'
Usage:
  devbot kube env      [path]   Print KUBECONFIG for the project (no credentials)
  devbot kube contexts [path]   List the clusters this project may reach
  devbot kube run      [path] -- <kubectl args...>

`path` defaults to the current directory. The kubeconfig is generated by
`devbot init`; run `devbot reinit <path>` if it is missing.
EOF
}

# Resolve the generated files for a project. Sets PROJECT_DIR, PROJECT_CONFIG,
# READER, SPEC, SELECTION, KUBECONFIG_PATH and ENV_PATH.
_resolve() {
  local dir="${1:-.}" slug selection
  if [[ ! -d "${dir}" ]]; then
    _error "not a directory: ${dir}"
    return 1
  fi
  PROJECT_DIR="$(cd "${dir}" && pwd)"
  PROJECT_CONFIG="${PROJECT_DIR}/.devbot.project.jsonc"
  READER="${MODULE_DIR}/../../_shared/read_jsonc.py"

  if [[ ! -f "${PROJECT_CONFIG}" ]]; then
    _error "no ${PROJECT_CONFIG}; run: devbot init ${PROJECT_DIR}"
    return 1
  fi

  SPEC="$(python3 "${READER}" "$(_devbot_global_config)" kubectl 2>/dev/null || true)"
  if [[ -z "${SPEC}" || "${SPEC}" == "null" ]]; then
    _error "no 'kubectl' node in $(_devbot_global_config)"
    return 1
  fi

  selection="$(python3 "${READER}" "${PROJECT_CONFIG}" kubectl 2>/dev/null || true)"
  if [[ -z "${selection}" || "${selection}" == "null" ]]; then
    _error "${PROJECT_CONFIG} selects no clusters; add a 'kubectl' array"
    return 1
  fi

  slug="$(_project_slug)"
  KUBECONFIG_PATH="${HOME}/.kube/devbot/${slug}.yaml"

  if [[ ! -f "${KUBECONFIG_PATH}" ]]; then
    _error "no generated kubeconfig at ${KUBECONFIG_PATH}; run: devbot reinit ${PROJECT_DIR}"
    return 1
  fi
}

# Context names actually in the generated kubeconfig.
# init.sh skips clusters it cannot describe.
_generated_contexts() {
  kubectl --kubeconfig "${KUBECONFIG_PATH}" config get-contexts -o name
}

# The ${VAR} references in credential_env: the variables the
# wrapper reads, and therefore what the environment must set.
_credential_refs() {
  jq -r '.credential_env // {}
    | to_entries[]
    | .value
    | select(test("^\\$\\{[A-Za-z_][A-Za-z0-9_]*\\}$"))
    | sub("^\\$\\{"; "") | sub("\\}$"; "")' <<<"${SPEC}" \
    | sort -u | tr '\n' ' ' | sed 's/ $//'
}

# The catalogue entry behind a context, as "name<TAB>region". A context name
# defaults to the cluster name but a catalogue entry may override it, so match
# on the effective context name rather than assuming the two are equal.
_catalogue_entry() {
  jq -r --arg ctx "$1" '
    .clusters[]
    | (if ((.context // "") | test("^[A-Za-z0-9._-]+$")) then .context else .name end) as $c
    | select($c == $ctx)
    | [.name, .region] | @tsv' <<<"${SPEC}" 2>/dev/null | head -1
}

cmd_env() {
  _resolve "${1:-.}" || return 1
  local current refs cluster
  current="$(awk '/^current-context:/{print $2; exit}' "${KUBECONFIG_PATH}")"
  IFS=$'\t' read -r cluster _ < <(_catalogue_entry "${current}") || true
  refs="$(_credential_refs)"
  printf 'export KUBECONFIG=%q\n' "${KUBECONFIG_PATH}"
  # kubectl ignores this; informational only — named with its cluster, because
  # the context alone is what gets skimmed past.
  if [[ -n "${cluster:-}" ]]; then
    printf '# current-context: %s (%s)\n' "${current}" "${cluster}"
  else
    printf '# current-context: %s\n' "${current}"
  fi
  printf '# credentials: %s must be set in the environment\n' "${refs:-<none configured>}"
}

cmd_contexts() {
  _resolve "${1:-.}" || return 1
  if ! command -v kubectl >/dev/null 2>&1; then
    _error "kubectl is not on PATH"
    return 1
  fi

  local contexts ctx name region
  if ! contexts="$(_generated_contexts)"; then
    _error "could not read contexts from ${KUBECONFIG_PATH}"
    return 1
  fi

  printf '%-10s %-18s %s\n' "NAME" "CONTEXT" "REGION"
  while IFS= read -r ctx; do
    [[ -n "${ctx}" ]] || continue
    IFS=$'\t' read -r name region < <(_catalogue_entry "${ctx}") || true
    printf '%-10s %-18s %s\n' "${name:--}" "${ctx}" "${region:--}"
  done <<<"${contexts}"
}

cmd_run() {
  local project="."
  if [[ "${1:-}" != "--" && $# -gt 0 ]]; then
    project="$1"
    shift
  fi
  [[ "${1:-}" == "--" ]] && shift

  _resolve "${project}" || return 1

  if ! command -v kubectl >/dev/null 2>&1; then
    _error "kubectl is not on PATH"
    return 1
  fi

  # These override file, cluster or identity; the
  # banner would then name the wrong target.
  local flag
  for flag in "$@"; do
    case "${flag}" in
      --kubeconfig | --kubeconfig=* | -s | -s=* | --server | --server=* | \
        --cluster | --cluster=* | --user | --user=* | \
        --token | --token=* | --as | --as=* | \
        --client-certificate | --client-certificate=* | \
        --client-key | --client-key=* | \
        --certificate-authority | --certificate-authority=* | \
        --insecure-skip-tls-verify | --insecure-skip-tls-verify=*)
        _error "refusing '${flag}': it would override the project's kubeconfig"
        return 1
        ;;
    esac
  done

  # The target goes to stderr, named with its catalogue cluster: the context
  # alone (`gete-prod-ro`) is easy to skim past, and an answer read from the
  # wrong cluster is reported as the other environment's until someone notices.
  local current cluster i
  current="$(awk '/^current-context:/{print $2; exit}' "${KUBECONFIG_PATH}")"
  local -a args=("$@")
  for ((i = 0; i < ${#args[@]}; i++)); do
    case "${args[i]}" in
      --context=*) current="${args[i]#--context=}" ;;
      --context) current="${args[i + 1]:-${current}}" ;;
    esac
  done
  IFS=$'\t' read -r cluster _ < <(_catalogue_entry "${current}") || true
  if [[ -n "${cluster:-}" ]]; then
    printf 'kubectl context: %s (%s)\n' "${current}" "${cluster}" >&2
  else
    printf 'kubectl context: %s\n' "${current}" >&2
  fi

  # The exec wrapper runs under `set -eu`: an unset credential
  # variable surfaces as an opaque plugin error, so check first.
  local key ref var
  while IFS=$'\t' read -r key ref; do
    [[ -n "${key}" ]] || continue
    [[ "${ref}" == '${'*'}' ]] || continue
    var="${ref#\$\{}"
    var="${var%\}}"
    if [[ -z "${!var:-}" ]]; then
      _error "${var} is not set; it backs ${key} in the global credential_env"
      return 1
    fi
  done < <(jq -r '.credential_env // {} | to_entries[] | "\(.key)\t\(.value)"' <<<"${SPEC}")

  # Credentials come from credential_env at exec time.
  # The .env carries only KUBECONFIG.
  exec kubectl --kubeconfig "${KUBECONFIG_PATH}" "$@"
}

main() {
  local cmd="${1:-}"
  if [[ $# -gt 0 ]]; then
    shift
  fi

  case "${cmd}" in
    env)
      cmd_env "${1:-.}"
      ;;
    contexts)
      cmd_contexts "${1:-.}"
      ;;
    run)
      cmd_run "$@"
      ;;
    "")
      _usage >&2
      exit 1
      ;;
    -h|--help|help)
      _usage
      ;;
    *)
      _error "unknown 'kube' subcommand: ${cmd}"
      _usage >&2
      exit 1
      ;;
  esac
}

main "$@"
